import { test, expect } from '@playwright/test';

test.describe('Marking a Record as Favourite', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully mark a record as favourite and update UI', async ({ page }) => {
    // Verify record list is visible
    const recordList = page.getByRole('region', { name: /record list/i });
    await expect(recordList).toBeVisible();

    // Get the first record row
    const firstRecordRow = page.locator('[data-testid="record-row-1"]');
    await expect(firstRecordRow).toBeVisible();

    // Get the favourite button using getByRole
    const favouriteButton = page.getByRole('button', { name: /favourite/i });
    await expect(favouriteButton).toBeVisible();

    // Click the favourite button
    await favouriteButton.click();

    // Verify favourite state is active
    await expect(favouriteButton).toHaveAttribute('aria-pressed', 'true');
    await expect(favouriteButton).toHaveClass(/is-favourite/);

    // Verify favourite icon is displayed
    const favouriteIcon = page.locator('[data-testid="favourite-icon"]');
    await expect(favouriteIcon).toBeVisible();

    // Verify success message appears
    const successMessage = page.getByText(/record marked as favourite/i);
    await expect(successMessage).toBeVisible();

    // Verify record is now in favourite list
    const favouriteList = page.getByRole('region', { name: /favourites/i });
    await expect(favouriteList).toBeVisible();
  });

  test('should handle unfavouriting a record and revert UI state', async ({ page }) => {
    // Get the first record row
    const firstRecordRow = page.locator('[data-testid="record-row-1"]');
    await expect(firstRecordRow).toBeVisible();

    // Get the favourite button using getByRole
    const favouriteButton = page.getByRole('button', { name: /favourite/i });
    await expect(favouriteButton).toBeVisible();

    // Click to favourite the record
    await favouriteButton.click();
    await expect(favouriteButton).toHaveAttribute('aria-pressed', 'true');

    // Get the favourite icon
    const favouriteIcon = page.locator('[data-testid="favourite-icon"]');
    await expect(favouriteIcon).toBeVisible();

    // Click the favourite button again to unfavourite
    await favouriteButton.click();

    // Verify favourite state is removed
    await expect(favouriteButton).toHaveAttribute('aria-pressed', 'false');
    await expect(favouriteButton).not.toHaveClass(/is-favourite/);

    // Verify favourite icon is no longer displayed
    await expect(favouriteIcon).not.toBeVisible();

    // Verify success message for unfavourite
    const unfavouriteMessage = page.getByText(/record removed from favourites/i);
    await expect(unfavouriteMessage).toBeVisible();
  });
});
